/* Interactive map of Talan (/setting/talan/interactive-map.html).
 *
 * Tiles: Wonderdraft's "Base" export (terrain, symbols, legend; no shapes or names),
 * cut into a Leaflet CRS.Simple pyramid under /setting/assets/maps/tiles/.
 * Overlays: region/domain shapes and name labels from /setting/assets/maps/map-data.json,
 * drawn as one SVG in map units so they scale with the map like Wonderdraft's own.
 * Both are generated by tools/wonderdraft (wd-regions --publish).
 */
(function () {
  'use strict';
  var DATA_URL = '/setting/assets/maps/map-data.json';
  var TILE_URL = '/setting/assets/maps/tiles/{z}/{x}/{y}.webp';
  var NS = 'http://www.w3.org/2000/svg';
  var LAYERS = ['regions', 'domains', 'region', 'god', 'divine', 'city', 'landmark'];
  var PRESETS = {
    terrain: ['divine', 'city', 'landmark'],
    regions: ['regions', 'region', 'divine', 'city', 'landmark'],
    domains: ['domains', 'god', 'divine']
  };
  var STORE = 'tyrnarra-map-layers';

  function el(name, attrs, parent) {
    var e = document.createElementNS(NS, name);
    for (var k in attrs) e.setAttribute(k, attrs[k]);
    if (parent) parent.appendChild(e);
    return e;
  }

  // Closed Catmull-Rom spline through the outline points, like Wonderdraft's "smoothing".
  function pathD(pts, smoothing) {
    var n = pts.length, k = smoothing > 0 ? Math.min(1, smoothing / 0.2) / 6 : 0;
    var d = 'M' + pts[0][0] + ' ' + pts[0][1];
    for (var i = 0; i < n; i++) {
      var p0 = pts[(i - 1 + n) % n], p1 = pts[i], p2 = pts[(i + 1) % n], p3 = pts[(i + 2) % n];
      if (!k) { d += 'L' + p2[0] + ' ' + p2[1]; continue; }
      d += 'C' + (p1[0] + (p2[0] - p0[0]) * k).toFixed(1) + ' ' + (p1[1] + (p2[1] - p0[1]) * k).toFixed(1) + ' ' +
           (p2[0] - (p3[0] - p1[0]) * k).toFixed(1) + ' ' + (p2[1] - (p3[1] - p1[1]) * k).toFixed(1) + ' ' +
           p2[0] + ' ' + p2[1];
    }
    return d + 'Z';
  }

  // Wonderdraft names fonts with the style inside ("Gentium Book Basic Bold").
  function cssFont(name) {
    var words = (name || 'serif').split(' '), weight = 'normal', style = 'normal';
    while (words.length > 1 && /^(bold|italic|regular)$/i.test(words[words.length - 1])) {
      var w = words.pop().toLowerCase();
      if (w === 'bold') weight = 'bold';
      if (w === 'italic') style = 'italic';
    }
    return { family: "'" + words.join(' ') + "', 'Crimson Pro', serif", weight: weight, style: style };
  }

  function escapeHtml(s) {
    return String(s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; });
  }

  function buildSvg(data) {
    var size = data.size[0];
    var svg = el('svg', { xmlns: NS, viewBox: '0 0 ' + size + ' ' + data.size[1], preserveAspectRatio: 'none' });
    var defs = el('defs', {}, svg);
    var groups = {};
    ['domains', 'regions'].forEach(function (g) { groups[g] = el('g', { 'class': 'wd-shapes', 'data-group': g }, svg); });
    var labelsRoot = el('g', { 'class': 'wd-labels' }, svg);
    ['god', 'region', 'divine', 'city', 'landmark'].forEach(function (g) { groups[g] = el('g', { 'data-group': g }, labelsRoot); });

    data.shapes.forEach(function (s, i) {
      var d = pathD(s.points, s.smoothing);
      var fillOpacity = (s.opacity || 0.25) * (s.kind === 'domain' ? Math.max(0.5, s.alpha) : 1);
      var g = groups[s.kind === 'domain' ? 'domains' : 'regions'];
      if (s.kind === 'region') {
        // Wonderdraft's gradient border glows inward: a wide stroke clipped to the shape.
        var clip = el('clipPath', { id: 'wd-clip-' + i }, defs);
        el('path', { d: d }, clip);
        el('path', { d: d, fill: 'none', stroke: s.color, 'stroke-width': s.width * 3, 'stroke-opacity': 0.5,
                     'clip-path': 'url(#wd-clip-' + i + ')', 'pointer-events': 'none' }, g);
      }
      var p = el('path', {
        d: d, 'class': 'wd-shape', fill: s.color, 'fill-opacity': fillOpacity.toFixed(3), stroke: s.color,
        'stroke-width': s.kind === 'domain' ? s.width : s.width * 0.35,
        'stroke-opacity': 0.9, 'stroke-dasharray': s.kind === 'domain' ? (s.width * 3.5) + ' ' + (s.width * 2.2) : 'none'
      }, g);
      p.__shape = s;
      var t = el('title', {}, p);
      t.textContent = s.name || '';
    });

    data.labels.forEach(function (l) {
      var f = cssFont(l.font), lines = l.text.split('\n');
      var t = el('text', {
        x: l.x, y: l.y, 'text-anchor': 'middle', 'dominant-baseline': 'central',
        'font-size': l.size, fill: l.color, stroke: l.outline_color, 'stroke-width': l.outline * 2,
        transform: l.rotation ? 'rotate(' + (l.rotation * 180 / Math.PI) + ' ' + l.x + ' ' + l.y + ')' : ''
      }, groups[l.group]);
      t.style.fontFamily = f.family; t.style.fontWeight = f.weight; t.style.fontStyle = f.style;
      lines.forEach(function (line, k) {
        var ts = el('tspan', { x: l.x, dy: k === 0 ? (-(lines.length - 1) * 0.6) + 'em' : '1.2em' }, t);
        ts.textContent = line;
      });
    });
    return { svg: svg, groups: groups };
  }

  function loadLayers() {
    try {
      var v = JSON.parse(localStorage.getItem(STORE));
      if (Array.isArray(v)) return v;
    } catch (e) { /* storage blocked or empty: fall back to the default view */ }
    return PRESETS.regions.slice();
  }

  function saveLayers(on) {
    try { localStorage.setItem(STORE, JSON.stringify(on)); } catch (e) { /* not essential */ }
  }

  function init(data) {
    var status = document.getElementById('map-status');
    var tools = document.getElementById('map-tools');
    var size = data.size[0], maxZ = data.max_zoom;
    // Whole zoom steps only: at fractional zoom the browser draws each tile at a fractional
    // position and hairline seams show between them.
    var map = L.map('talan-map', { crs: L.CRS.Simple, minZoom: 0, maxZoom: maxZ + 2, zoomSnap: 1,
                                   zoomDelta: 1, attributionControl: false });
    var bounds = L.latLngBounds(map.unproject([0, size], maxZ), map.unproject([size, 0], maxZ));
    L.tileLayer(TILE_URL, { tileSize: data.tile, noWrap: true, bounds: bounds, minZoom: 0,
                            maxNativeZoom: maxZ, maxZoom: maxZ + 2 }).addTo(map);
    map.fitBounds(bounds);
    map.setMaxBounds(bounds.pad(0.15));

    var built = buildSvg(data);
    L.svgOverlay(built.svg, bounds, { interactive: true }).addTo(map);

    // Clicks on shapes open a popup; a drag that ends on a shape is not a click.
    var downAt = null;
    built.svg.addEventListener('pointerdown', function (e) { downAt = [e.clientX, e.clientY]; });
    built.svg.addEventListener('click', function (e) {
      var s = e.target.__shape;
      if (!s || (downAt && Math.abs(e.clientX - downAt[0]) + Math.abs(e.clientY - downAt[1]) > 6)) return;
      // Otherwise the same click reaches the map, which closes popups on click.
      L.DomEvent.stopPropagation(e);
      var kind = s.kind === 'domain' ? 'God domain' : (s.domain ? 'Region of ' + escapeHtml(s.domain) : 'Region');
      var link = s.href ? '<a href="' + escapeHtml(s.href) + '">Open the page →</a>' : '<span class="pop-kind">No page yet</span>';
      L.popup().setLatLng(map.mouseEventToLatLng(e))
        .setContent('<div class="pop-name">' + escapeHtml(s.name || 'Unnamed') + '</div><div class="pop-kind">' + kind +
                    '</div><div>' + link + '</div>').openOn(map);
    });

    var boxes = tools.querySelectorAll('input[data-layer]');
    var buttons = tools.querySelectorAll('button[data-preset]');
    function apply(on) {
      LAYERS.forEach(function (name) { built.groups[name].style.display = on.indexOf(name) >= 0 ? '' : 'none'; });
      Array.prototype.forEach.call(boxes, function (b) { b.checked = on.indexOf(b.dataset.layer) >= 0; });
      Array.prototype.forEach.call(buttons, function (b) {
        var p = PRESETS[b.dataset.preset];
        b.setAttribute('aria-pressed', String(p.length === on.length && p.every(function (x) { return on.indexOf(x) >= 0; })));
      });
      saveLayers(on);
    }
    Array.prototype.forEach.call(boxes, function (b) {
      b.addEventListener('change', function () {
        apply(Array.prototype.filter.call(boxes, function (x) { return x.checked; }).map(function (x) { return x.dataset.layer; }));
      });
    });
    Array.prototype.forEach.call(buttons, function (b) {
      b.addEventListener('click', function () { apply(PRESETS[b.dataset.preset].slice()); });
    });
    apply(loadLayers());
    tools.hidden = false;
    status.hidden = true;
  }

  function start() {
    fetch(DATA_URL).then(function (r) {
      if (!r.ok) throw new Error(r.status);
      return r.json();
    }).then(init).catch(function () {
      document.getElementById('map-status').textContent = 'The map could not be loaded.';
    });
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start);
  else start();
})();
